var PageQuery = external_exports.object({
  pageSize: external_exports.coerce.number().int().min(1).max(200).default(50),
  pageToken: external_exports.string().optional()
});
function readPage(query2) {
  if (!query2.pageToken) return { limit: query2.pageSize, offset: 0 };
  try {
    const { o } = JSON.parse(Buffer.from(query2.pageToken, "base64url").toString("utf8"));
    if (!Number.isInteger(o) || o < 0) throw new Error("bad offset");
    return { limit: query2.pageSize, offset: o };
  } catch {
    throw new AppError(400, "VALIDATION_FAILED", "Invalid pageToken");
  }
}
function toPage(rows, page) {
  const hasMore = rows.length > page.limit;
  const items = hasMore ? rows.slice(0, page.limit) : rows;
  const nextPageToken = hasMore ? Buffer.from(JSON.stringify({ o: page.offset + page.limit })).toString("base64url") : null;
  return { items, nextPageToken };
}

