// ../api/src/modules/documents/amount-in-words.ts
var ONES = [
  "",
  "One",
  "Two",
  "Three",
  "Four",
  "Five",
  "Six",
  "Seven",
  "Eight",
  "Nine",
  "Ten",
  "Eleven",
  "Twelve",
  "Thirteen",
  "Fourteen",
  "Fifteen",
  "Sixteen",
  "Seventeen",
  "Eighteen",
  "Nineteen"
];
var TENS = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
function belowHundred(n2) {
  if (n2 < 20) return ONES[n2];
  return `${TENS[Math.floor(n2 / 10)]}${n2 % 10 ? ` ${ONES[n2 % 10]}` : ""}`;
}
function belowThousand(n2) {
  const hundreds = Math.floor(n2 / 100);
  const rest = n2 % 100;
  return [hundreds ? `${ONES[hundreds]} Hundred` : "", rest ? belowHundred(rest) : ""].filter(Boolean).join(" ");
}
function numberInWords(n2) {
  if (n2 === 0) return "Zero";
  const parts = [];
  const crore = Math.floor(n2 / 1e7);
  const lakh = Math.floor(n2 % 1e7 / 1e5);
  const thousand = Math.floor(n2 % 1e5 / 1e3);
  const rest = n2 % 1e3;
  if (crore) parts.push(`${numberInWords(crore)} Crore`);
  if (lakh) parts.push(`${belowHundred(lakh)} Lakh`);
  if (thousand) parts.push(`${belowHundred(thousand)} Thousand`);
  if (rest) parts.push(belowThousand(rest));
  return parts.join(" ");
}
function amountInWords(amount) {
  const d = new Decimal(amount).toDecimalPlaces(2);
  const rupees = d.floor().toNumber();
  const paise = d.minus(d.floor()).mul(100).toNumber();
  return `Rupees ${numberInWords(rupees)}${paise ? ` and ${belowHundred(paise)} Paise` : ""} Only`;
}

