async function resolveCustomer(c, input2) {
  const branch = await loadActiveBranch(c, input2.branchId);
  const party = input2.partyId ? await queryOne(c, "SELECT * FROM erp.parties WHERE id = $1", [input2.partyId]) : null;
  if (input2.partyId && !party) throw new AppError(422, "INVALID_REFERENCE", "Customer not found");
  if (party && party.kind === "supplier")
    throw new AppError(422, "BUSINESS_RULE", `"${party.name}" is not a customer`);
  if (party && !party.is_active)
    throw new AppError(422, "BUSINESS_RULE", `"${party.name}" is inactive`);
  const supplyType = party?.gstin ? "b2b" : "b2c";
  const placeOfSupply = input2.placeOfSupply ?? party?.state_code ?? branch.state_code;
  return {
    branch,
    supplyType,
    interState: placeOfSupply !== branch.state_code,
    /** Snapshot columns, identical on invoices and quotations. */
    columns: {
      branch_id: branch.id,
      supply_type: supplyType,
      party_id: party?.id ?? null,
      customer_name: party?.name ?? input2.customerName ?? "Cash Sale",
      customer_gstin: party?.gstin ?? null,
      customer_phone: input2.customerPhone ?? party?.phone ?? null,
      billing_address: input2.billingAddress ?? party?.billing_address ?? null,
      shipping_address: input2.shippingAddress ?? party?.shipping_address ?? null,
      place_of_supply: placeOfSupply,
      seller_state_code: branch.state_code
    }
  };
}

