    path: "/purchase-bills",
    table: "erp.purchase_bills",
    entity: "Purchase bill",
    load: loadPurchaseBill,
    post: { fn: "post_purchase_bill", roles: Permissions.purchase },
    cancel: { fn: "cancel_purchase_bill", roles: Permissions.cancelPurchase },
