var StockQuery = external_exports.object({
  branchId: Uuid.optional(),
  search: external_exports.string().trim().optional(),
  lowOnly: external_exports.enum(["true", "false"]).default("false").transform((v) => v === "true")
});
var MovementsQuery = PageQuery.extend({ productId: Uuid.optional(), branchId: Uuid.optional() });
var AdjustmentBody = external_exports.object({
  branchId: Uuid,
  productId: Uuid,
  /** Positive adds stock, negative removes it. */
  qtyChange: Quantity.refine((v) => Number(v) !== 0, "Cannot be zero"),
  reason: NonEmpty,
  isOpening: external_exports.boolean().default(false)
});
function registerStockRoutes(app, { guards }) {
  app.get("/stock", { preHandler: guards.tenant(Permissions.read) }, async (request) => {
    const q = StockQuery.parse(request.query);
    const rows = await request.tx(
      (c) => query(
        c,
        `SELECT s.*, p.thickness_mm, p.attributes
         FROM erp.v_stock s
         JOIN erp.products p ON p.id = s.product_id
         WHERE ($1::uuid IS NULL OR s.branch_id = $1)
           AND ($2::text IS NULL
                OR s.name ILIKE $2
                OR s.sku ILIKE $2
                OR coalesce(p.attributes->>'length', '') || ' ' || coalesce(p.attributes->>'lengthUnit', '') ILIKE $2
                OR coalesce(p.thickness_mm::text, '') || 'mm' ILIKE $2)
           AND (NOT $3 OR s.needs_reorder)
         ORDER BY lower(s.name)`,
        [q.branchId ?? null, q.search ? containsPattern(q.search) : null, q.lowOnly]
      )
    );
    return {
      items: rows.map((r) => ({
        branchId: r.branch_id,
        productId: r.product_id,
        sku: r.sku,
        name: r.name,
        kind: r.kind,
        unitCode: r.unit_code,
        thicknessMm: r.thickness_mm,
        attributes: r.attributes,
        qty: r.qty,
        reorderLevel: r.reorder_level,
        needsReorder: r.needs_reorder
      }))
    };
  });
  app.get("/stock/movements", { preHandler: guards.tenant(Permissions.read) }, async (request) => {
    const q = MovementsQuery.parse(request.query);
    const page = readPage(q);
    const rows = await request.tx(
      (c) => query(
        c,
        `SELECT * FROM erp.stock_movements
         WHERE ($1::uuid IS NULL OR product_id = $1) AND ($2::uuid IS NULL OR branch_id = $2)
         ORDER BY id DESC
         LIMIT $3 OFFSET $4`,
        [q.productId ?? null, q.branchId ?? null, page.limit + 1, page.offset]
      )
    );
    const result = toPage(rows, page);
    return {
      items: result.items.map((m) => ({
        id: m.id,
        branchId: m.branch_id,
        productId: m.product_id,
        type: m.movement_type,
        qtyChange: m.qty_change,
        balanceAfter: m.balance_after,
        refType: m.ref_type,
        refId: m.ref_id,
        note: m.note,
        createdAt: m.created_at,
        createdBy: m.created_by
      })),
      nextPageToken: result.nextPageToken
    };
  });
  app.post(
    "/stock/adjustments",
    { preHandler: guards.tenant(Permissions.adjustStock) },
    async (request, reply) => {
      const b = AdjustmentBody.parse(request.body);
      const row = await request.tx(
        (c) => queryOne(c, "SELECT erp.adjust_stock($1, $2, $3, $4, $5)::text AS qty", [
          b.branchId,
          b.productId,
          b.qtyChange,
          b.reason,
          b.isOpening
        ])
      );
      return reply.status(201).send({ branchId: b.branchId, productId: b.productId, qty: row.qty });
    }
  );
}

// ../api/src/app.ts
async function buildApp({ config: config3, pool }) {
  configurePgTypes();
  const app = (0, import_fastify.default)({
    logger: { level: config3.LOG_LEVEL },
    requestIdHeader: "x-request-id",
    genReqId: () => (0, import_node_crypto4.randomUUID)(),
    trustProxy: typeof config3.TRUST_PROXY === "number" ? (_address, hop) => hop < config3.TRUST_PROXY : config3.TRUST_PROXY,
    bodyLimit: 1024 * 1024
  });
  const tokens = new TokenService(config3.JWT_SECRET, config3.ACCESS_TOKEN_TTL_SECONDS);
  const ctx = { config: config3, pool, tokens, guards: createGuards(pool, tokens) };
  app.decorateRequest("auth", null);
  app.decorateRequest("tx", function(work) {
    return withTransaction(
      pool,
      {
        requestId: this.id,
        userId: this.auth?.userId ?? null,
        tenantId: this.auth?.tenantId ?? null,
        clientIp: this.ip
      },
      work
    );
  });
  app.setErrorHandler(errorHandler);
  app.addHook("onSend", async (request, reply) => {
    reply.header("x-request-id", request.id);
  });
  await registerSecurity(app, config3);
  if (config3.WEB_DIST_DIR) {
    await serveWebApp(app, config3.WEB_DIST_DIR);
    app.get("/", (_request, reply) => reply.sendFile("index.html"));
  } else {
    app.get("/", async () => ({
      service: "Glass ERP API",
      version: "v1",
      health: "/healthz",
      ready: "/readyz",
      docs: "docs/02-api.md in the repository"
    }));
  }
  app.setNotFoundHandler((request, reply) => {
    if (config3.WEB_DIST_DIR && isAppPage(request.method, request.url, request.headers.accept)) {
      return reply.sendFile("index.html");
    }
    throw new AppError(404, "NOT_FOUND", `No route ${request.method} ${request.url}`);
  });
  app.get("/healthz", async () => ({ status: "ok" }));
  app.get("/readyz", async () => {
    await pool.query("SELECT 1");
    return { status: "ok" };
  });
  await app.register(
    async (v12) => {
      registerAuthRoutes(v12, ctx);
      registerReferenceRoutes(v12, ctx);
      registerTenantRoutes(v12, ctx);
      registerMemberRoutes(v12, ctx);
      registerBranchRoutes(v12, ctx);
      registerProductRoutes(v12, ctx);
      registerPartyRoutes(v12, ctx);
      registerStockRoutes(v12, ctx);
      registerDashboardRoutes(v12, ctx);
      registerQuotationRoutes(v12, ctx);
      registerSalesInvoiceRoutes(v12, ctx);
      registerReceiptRoutes(v12, ctx);
      registerCreditNoteRoutes(v12, ctx);
      registerPurchaseBillRoutes(v12, ctx);
      registerSupplierPaymentRoutes(v12, ctx);
      registerGstPeriodRoutes(v12, ctx);
      registerReportRoutes(v12, ctx);
    },
    { prefix: "/v1" }
  );
  return app;
}

