var flag = external_exports.enum(["true", "false"]).transform((v) => v === "true");
var EnvSchema = external_exports.object({
  NODE_ENV: external_exports.enum(["development", "test", "production"]).default("development"),
  HOST: external_exports.string().default("0.0.0.0"),
  PORT: external_exports.coerce.number().int().positive().default(4e3),
  LOG_LEVEL: external_exports.enum(["fatal", "error", "warn", "info", "debug", "trace", "silent"]).default("info"),
  DATABASE_URL: external_exports.url(),
  DATABASE_POOL_SIZE: external_exports.coerce.number().int().positive().default(10),
  JWT_SECRET: external_exports.string().min(32, "JWT_SECRET must be at least 32 characters"),
  ACCESS_TOKEN_TTL_SECONDS: external_exports.coerce.number().int().positive().default(900),
  REFRESH_TOKEN_TTL_DAYS: external_exports.coerce.number().int().positive().default(30),
  /**
   * Which proxies to believe about the client's IP (X-Forwarded-For). The IP is
   * used for rate limiting and the audit log, so never trust every hop:
   *   false (default)   no proxy in front: use the socket address
   *   1                 exactly one proxy (nginx/Caddy on the same machine)
   *   127.0.0.1,10.0.0.5  only these proxy addresses
   */
  TRUST_PROXY: external_exports.string().default("false").transform(
    (v) => v === "false" ? false : /^\d+$/.test(v) ? Number(v) : v.split(",").map((s) => s.trim())
  ),
  /** Send the login cookie over HTTPS only. Defaults to true in production. */
  COOKIE_SECURE: flag.optional(),
  /** Requests per minute per IP, for everything / for sign-in and sign-up. */
  RATE_LIMIT_PER_MINUTE: external_exports.coerce.number().int().positive().default(600),
  AUTH_RATE_LIMIT_PER_MINUTE: external_exports.coerce.number().int().positive().default(10),
  /** The built web app (web/dist). When set, the API serves it on the same origin. */
  WEB_DIST_DIR: external_exports.string().optional()
});
function loadConfig(env2 = process.env) {
  const result = EnvSchema.safeParse(env2);
  if (!result.success) {
    throw new Error(`Invalid environment configuration:
${external_exports.prettifyError(result.error)}`);
  }
  const c = result.data;
  return { ...c, COOKIE_SECURE: c.COOKIE_SECURE ?? c.NODE_ENV === "production" };
}

// api/_entry.js
var appPromise = null;
function getApp() {
  if (!appPromise) {
    appPromise = (async () => {
      const rawDbUrl = (process.env.DATABASE_URL || "").trim();
      if (!rawDbUrl) throw new Error("DATABASE_URL environment variable is not set");
      const cleanDbUrl = rawDbUrl.replace(
        /([?&])channel_binding=require(&?)/,
        (_2, p1, p2) => p2 ? p1 : ""
      );
      const rawJwt = (process.env.JWT_SECRET || "").trim();
      if (rawJwt.length < 32) throw new Error("JWT_SECRET must be set (min 32 chars)");
      const jwtSecret = rawJwt;
      const cfg = loadConfig({
        ...process.env,
        DATABASE_URL: cleanDbUrl,
        JWT_SECRET: jwtSecret,
        NODE_ENV: process.env.NODE_ENV ?? "production",
        TRUST_PROXY: process.env.TRUST_PROXY ?? "1",
        DATABASE_POOL_SIZE: process.env.DATABASE_POOL_SIZE ?? "3"
      });
      const pool = createPool({
        connectionString: cfg.DATABASE_URL,
        max: cfg.DATABASE_POOL_SIZE,
        onError: (err) => console.error("idle database client error", err)
      });
      const app = await buildApp({ config: cfg, pool });
      await app.ready();
      return app;
    })().catch((err) => {
      appPromise = null;
      throw err;
    });
  }
  return appPromise;
}
async function handleRequest(req, res) {
  const app = await getApp();
  await new Promise((resolve2) => {
    res.once("finish", resolve2);
    res.once("close", resolve2);
    app.server.emit("request", req, res);
  });
}
